function symbol_scene(bg,auraColor,symbol,label,extra){
  return '<div class="fs-scene" style="background:'+bg+';display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px">'
    +'<div class="aura" style="width:220px;height:220px;top:8%;left:50%;margin-left:-110px;background:radial-gradient(circle,'+auraColor+',transparent 70%)"></div>'
    +'<div style="font-size:5.5rem;z-index:5;filter:drop-shadow(0 0 28px '+auraColor+');animation:orbP 3s ease-in-out infinite">'+symbol+'</div>'
    +(extra?'<div style="z-index:5;display:flex;gap:10px">'+extra+'</div>':'')
    +'<div style="position:absolute;bottom:11%;left:0;right:0;text-align:center;font-family:Amiri,serif;font-size:.8rem;color:rgba(212,160,23,.7)">'+label+'</div>'
    +'</div>';
}
function sahaba_scene(bg,auraColor,svgArgs,label){
  var symbolMap={
    '📜':'📜','⚖️':'⚖️','📖':'📖','🛡':'🛡','⚔️':'⚔️','🗡':'🗡',
    '💰':'💰','🏹':'🏹','🌿':'🌿','🛡':'🛡','🔥':'🔥','👑':'👑',
    '🕌':'🕌','🌺':'🌺','📚':'📚','⭐':'⭐','🌟':'🌟','❤':'❤',
    '🗺':'🗺','⚡':'⚡'
  };
  var m=label.match(/[\u{1F300}-\u{1FAFF}]|[\u2600-\u27BF]/u);
  var sym=m?m[0]:'✨';
  return symbol_scene(bg,auraColor,sym,label,'');
}
function sc(bg,particles,icon,title,cards,extra){
  var pcss='';
  if(particles==='stars'){
    pcss='<canvas id="pcanv" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1"></canvas><script>setTimeout(function(){var c=document.getElementById("pcanv");if(!c)return;var ctx=c.getContext("2d");c.width=c.offsetWidth;c.height=c.offsetHeight;var pts=[];for(var i=0;i<36;i++)pts.push({x:Math.random()*c.width,y:Math.random()*c.height,r:Math.random()*1.3+.3,o:Math.random()});var raf=0;function dr(){if(document.hidden||document.documentElement.classList.contains("nr-hidden")){raf=0;return;}ctx.clearRect(0,0,c.width,c.height);pts.forEach(function(p){ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle="rgba(255,220,80,"+p.o+")";ctx.fill();p.o+=(.008*(Math.random()>.5?1:-1));if(p.o>1)p.o=1;if(p.o<.1)p.o=.1;});raf=requestAnimationFrame(dr);}function resume(){if(!document.hidden&&!document.documentElement.classList.contains("nr-hidden")&&!raf)dr();}document.addEventListener("visibilitychange",resume,{passive:true});document.addEventListener("rfq:visual-resume",resume,{passive:true});dr();},200);<\/script>';
  } else if(particles==='fire'){
    pcss='';
  }
  var cardsHtml=cards.map(function(c2){return '<div style="background:rgba(212,160,23,.07);border:1px solid rgba(212,160,23,.18);border-radius:12px;padding:9px 12px;text-align:right;max-width:300px;width:100%"><div style="font-size:1.2rem;margin-bottom:4px">'+c2[0]+'</div><div style="font-family:Amiri,serif;font-size:.84rem;color:var(--gold);margin-bottom:3px">'+c2[1]+'</div><div style="font-size:.76rem;color:var(--text2);line-height:1.6">'+c2[2]+'</div></div>';}).join('');
  return '<div style="width:100%;height:100%;'+bg+';display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;overflow:hidden;gap:12px;padding:55px 14px 14px">'+pcss+'<div style="font-size:3.8rem;animation:orbP 3s ease-in-out infinite;filter:drop-shadow(0 0 18px rgba(251,191,36,.5));z-index:5">'+icon+'</div><div style="font-family:Amiri,serif;font-size:1.2rem;color:var(--gold);text-align:center;z-index:5;text-shadow:0 0 16px rgba(251,191,36,.4)">'+title+'</div>'+cardsHtml+'</div>';
}
function card(icon,title,body){
  return '<div style="background:rgba(212,160,23,.07);border:1px solid rgba(212,160,23,.18);border-radius:11px;padding:8px 11px;text-align:right;max-width:300px;width:100%;flex-shrink:0"><div style="font-size:1.1rem;margin-bottom:3px">'+icon+'</div><div style="font-family:Amiri,serif;font-size:.82rem;color:var(--gold);margin-bottom:2px">'+title+'</div><div style="font-size:.74rem;color:var(--text2);line-height:1.55">'+body+'</div></div>';
}
function vp(icon,title,desc,extra){
  return '<div class="vpage"><div class="vic">'+icon+'</div><div class="vtitle">'+title+'</div><p class="vdesc">'+desc+'</p>'+(extra||'')+'</div>';
}
function hadith(text,source){
  return '<div class="vhadith">'+text+'<span style="display:block;font-size:.68rem;color:rgba(212,160,23,.55);margin-top:5px">('+source+')</span></div>';
}
function scene2(bg,icon,label,body){
  return '<div style="width:100%;height:100%;'+bg+';display:flex;flex-direction:column;align-items:center;justify-content:flex-start;position:relative;overflow-y:auto;gap:12px;padding:55px 16px 14px"><div style="font-size:3.2rem;animation:float 3s ease-in-out infinite;filter:drop-shadow(0 0 18px rgba(251,191,36,.5));flex-shrink:0">'+icon+'</div><div style="font-family:Amiri,serif;font-size:1.05rem;color:var(--gold);text-align:center;flex-shrink:0">'+label+'</div>'+body+'</div>';
}
